def uniq(lst):
    d = {}
    for x in lst:
        d[x] = True
    return sorted(d.keys())

src_hits = repo.search("OldClient", glob = "src/**")
for path in uniq([h.path for h in src_hits]):
    repo.edit(path, "OldClient", "NewClient", all = True)

# Verify
remaining_src = repo.search("OldClient", glob = "src/**")
remaining_docs = repo.search("OldClient", glob = "docs/**")
new_src = repo.search("NewClient", glob = "src/**")

commit()
return {
    "remaining_old_in_src": remaining_src,
    "remaining_old_in_docs": [(h.path, h.line, h.text) for h in remaining_docs],
    "new_in_src": [(h.path, h.line, h.text) for h in new_src],
    "a": repo.read("src/a.txt"),
    "b": repo.read("src/nested/b.txt"),
    "docs": repo.read("docs/history.txt"),
    "diff": repo.diff(),
}
